    static IDENT_RE: Lazy<Regex> =
        Lazy::new(|| Regex::new(r"[A-Za-z_][A-Za-z0-9_]*").expect("valid ident regex"));
    static RESERVED: Lazy<HashSet<&'static str>> = Lazy::new(|| {
        HashSet::from([
            "and",
            "as",
            "block",
            "break",
            "continue",
            "elif",
            "else",
            "endblock",
            "endfilter",
            "endif",
            "endfor",
